import sys
from math import factorial

def is_lucky(x):
    while x > 0:
        d = x % 10
        if d != 4 and d != 7:
            return False
        x //= 10
    return True

def generate_lucky(limit):
    res = []
    def dfs(cur):
        if cur > limit:
            return
        if cur != 0:
            res.append(cur)
        dfs(cur * 10 + 4)
        dfs(cur * 10 + 7)
    dfs(0)
    return sorted(res)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])

    # limit for factorial to avoid overflow and huge computations
    MAX_FACT_N = 20

    # if n is large, only last up to 20 positions matter for permutation generation
    if n > MAX_FACT_N:
        prefix_len = n - MAX_FACT_N
        # number of permutations of last MAX_FACT_N elements
        total_perm = 1
        for i in range(2, MAX_FACT_N + 1):
            total_perm *= i
        if k > total_perm:
            print(-1)
            return
        start = prefix_len + 1
        m = MAX_FACT_N
    else:
        # full permutation
        total_perm = 1
        for i in range(2, n + 1):
            total_perm *= i
        if k > total_perm:
            print(-1)
            return
        start = 1
        m = n
        prefix_len = 0

    # generate lucky indices up to n
    lucky_indices = generate_lucky(n)

    # count lucky positions in prefix (fixed as 1..prefix_len)
    ans = 0
    for idx in lucky_indices:
        if idx <= prefix_len and is_lucky(idx):
            ans += 1

    # generate k-th permutation of numbers [start..n]
    # k is 1-based
    k -= 1
    nums = list(range(start, n + 1))
    perm = [0] * m
    fact = [1] * (m + 1)
    for i in range(1, m + 1):
        fact[i] = fact[i - 1] * i

    for i in range(m):
        f = fact[m - 1 - i]
        idx = k // f
        k %= f
        perm[i] = nums[idx]
        nums.pop(idx)

    # check lucky positions in suffix
    for idx in lucky_indices:
        if idx > prefix_len:
            pos = idx - prefix_len - 1  # 0-based in perm
            if 0 <= pos < m:
                if is_lucky(perm[pos]):
                    ans += 1

    print(ans)

if __name__ == "__main__":
    main()
